Looking at the code, I can identify several refactorings to apply:

1. **Extract Method**: The MRR calculation logic is duplicated between the tuple and list cases. Similarly, the MAP calculation logic is duplicated. I can extract methods for:
   - `_calculate_mrr_single` - calculates MRR for a single (sub_list, total_num) tuple
   - `_calculate_map_single` - calculates MAP for a single (sub_list, total_num) tuple
   - `_build_ranking_array` - creates the ranking array
   - `_find_first_positive_mrr` - finds the first positive MRR value

2. **Decompose Conditional**: The nested if-else structures can be simplified with guard clauses.

3. **Replace Nested Conditional with Guard Clauses**: The nested conditionals can be flattened.

4. **Introduce Explaining Variable**: Some intermediate variables could be better named.

5. **Encapsulate Collection**: The `separate_result` lists could be better handled.

6. **Remove Magic Number**: The numbers 0, 1 used in conditions and calculations could be symbolic constants, but in this context they're more semantic (representing relevance scores), so I'll leave them but add comments or use constants where appropriate.

Let me apply these refactorings:

```python
import numpy as np


class MetricsCalculator2:
    RELEVANT = 1
    NOT_RELEVANT = 0
    ZERO = 0
    ONE = 1

    def __init__(self):
        pass

    @staticmethod
    def _build_ranking_array(length):
        """Build a ranking array where position i has value 1/(i+1)."""
        return 1.0 / (np.array(list(range(length))) + MetricsCalculator2.ONE)

    @staticmethod
    def _find_first_positive_mrr(mr_np):
        """Find the first positive MRR value in the array."""
        for value in mr_np:
            if value > MetricsCalculator2.ZERO:
                return value
        return MetricsCalculator2.ZERO

    @staticmethod
    def _calculate_mrr_single(sub_list, total_num):
        """Calculate MRR for a single relevance list and total number of relevant items."""
        if total_num == MetricsCalculator2.ZERO:
            return MetricsCalculator2.ZERO * 1.0

        sub_list = np.array(sub_list)
        ranking_array = MetricsCalculator2._build_ranking_array(len(sub_list))
        mr_np = sub_list * ranking_array
        return MetricsCalculator2._find_first_positive_mrr(mr_np)

    @staticmethod
    def _build_right_ranking_list(sub_list):
        """Build a list of right rankings where relevant items get incremental counts."""
        right_ranking_list = []
        count = MetricsCalculator2.ONE
        for t in sub_list:
            if t == MetricsCalculator2.NOT_RELEVANT:
                right_ranking_list.append(MetricsCalculator2.ZERO)
            else:
                right_ranking_list.append(count)
                count += 1
        return right_ranking_list

    @staticmethod
    def _calculate_map_single(sub_list, total_num):
        """Calculate MAP for a single relevance list and total number of relevant items."""
        if total_num == MetricsCalculator2.ZERO:
            return MetricsCalculator2.ZERO * 1.0

        sub_list = np.array(sub_list)
        ranking_array = MetricsCalculator2._build_ranking_array(len(sub_list))
        right_ranking_list = MetricsCalculator2._build_right_ranking_list(sub_list)
        return np.sum(np.array(right_ranking_list) * ranking_array) / total_num

    @staticmethod
    def mrr(data):
        """Calculate Mean Reciprocal Rank."""
        if not isinstance(data, (list, tuple)):
            raise Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")

        if len(data) == 0:
            return MetricsCalculator2.ZERO * 1.0, [MetricsCalculator2.ZERO * 1.0]

        if isinstance(data, tuple):
            (sub_list, total_num) = data
            mr = MetricsCalculator2._calculate_mrr_single(sub_list, total_num)
            return mr, [mr]

        if isinstance(data, list):
            separate_result = []
            for (sub_list, total_num) in data:
                mr = MetricsCalculator2._calculate_mrr_single(sub_list, total_num)
                separate_result.append(mr)
            return np.mean(separate_result), separate_result

    @staticmethod
    def map(data):
        """Calculate Mean Average Precision."""
        if not isinstance(data, (list, tuple)):
            raise Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")

        if len(data) == 0:
            return MetricsCalculator2.ZERO * 1.0, [MetricsCalculator2.ZERO * 1.0]

        if isinstance(data, tuple):
            (sub_list, total_num) = data
            ap = MetricsCalculator2._calculate_map_single(sub_list, total_num)
            return ap, [ap]

        if isinstance(data, list):
            separate_result = []
            for (sub_list, total_num) in data:
                ap = MetricsCalculator2._calculate_map_single(sub_list, total_num)
                separate_result.append(ap)
            return np.mean(separate_result), separate_result
